@Component("floor-entity-projector")
public class FloorEntityProjector implements EntityProjector<Floor>{
		
	// core constructor
	public FloorEntityProjector(ProjectorRegistry registry,
										FloorRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Floor> getEntityClass() {
		return Floor.class;
	}

    /*
	 * Insert a Floor
	 * 
     * @param	entity Floor
     */
    public Floor create( Floor entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Floor
	 * 
     * @param	entity Floor
     */
    public Floor update( Floor entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Floor
	 * 
     * @param	id		UUID
     */
    public Floor delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Floor entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Building
     * 
     * @param	parentId	UUID
     * @param	assignment 	Building 
     * @return	Floor
     */
    public Floor assignBuilding( UUID parentId, Building assignment ) {
	    LOGGER.info("assigning Building as " + assignment.toString() );

	    Floor parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Building.class, assignment.getBuildingId());

	    // ------------------------------------------
		// assign the Building to the parent entity
		// ------------------------------------------ 
	    parentEntity.setBuilding( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Building
	 * 
	 * @param	parentId		UUID
	 * @return	Floor
	 */
	public Floor unAssignBuilding( UUID parentId ) {
		Floor parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Building on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Building on the parent entithy
		// ------------------------------------------     
	    parentEntity.setBuilding(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Rooms
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Floor
     */
    public Floor addToRooms( UUID parentId, Room addTo ) {
	    LOGGER.info("handling AssignRoomsToFloorEvent - " );
	    
	    Floor parentEntity = repository.findById(parentId).get();
	    Room child = registry.project( Room.class, addTo.getRoomId());
	    
	    parentEntity.getRooms().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Rooms
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Floor
     */
	public Floor removeFromRooms( UUID parentId, Room removeFrom ) {
	    LOGGER.info("handling RemoveRoomsFromFloorEvent " );
	
	    Floor parentEntity = repository.findById(parentId).get();
	    Room child = registry.project( Room.class, removeFrom.getRoomId());
	    
	    parentEntity.getRooms().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Floor via an FindFloorQuery
     * @return 	query	FindFloorQuery
     */
    @SuppressWarnings("unused")
    public Floor find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Floor - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Floors
     *
     * @param	query	FindAllFloorQuery 
     * @return 	List<Floor> 
     */
    @SuppressWarnings("unused")
    public List<Floor> findAll( FindAllFloorQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Floor - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final FloorRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(FloorEntityProjector.class.getName());

}
